head.script:
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById("G_" + $p.id + "grd_EmpInfo1__DEPTNO").getValue() == '1_test3';
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#G_grd_EmpInfo1__DEPTNO').simulate('keydown', {
        key: 'ENTER',
        keyCode: 13,
        code: 13
    });
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1.
    //1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_EmpInfo1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grd_EmpInfo1__DEPTNO').focus()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1.
    //2.
    WebSquare.wUnit.addCommand("assert", "document.activeElement.tagName", "INPUT");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
            "DEPTNO": "1_test1",
            "DNAME": "2_test1",
            "LOC": ""
        },
        {
            "DEPTNO": "1_test2",
            "DNAME": "2_test2",
            "LOC": ""
        },
        {
            "DEPTNO": "1_test3",
            "DNAME": "2_test3",
            "LOC": ""
        },
        {
            "DEPTNO": "1_test4",
            "DNAME": "2_test4",
            "LOC": ""
        }
    ];
    dlt_EmpInfo.setJSON(jsonData);
    grd_EmpInfo1.setCellReadOnly(1, "DEPTNO", true);
    grd_EmpInfo1.setCellReadOnly(0, "DNAME", true);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 16-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
